      "revision": "fda3d8ee46b05d4da5968e39f21d97f172af82b44dd93b24aab31cab4b9bc638",
      "topic": "GI",
      "track": "gi/hirschsprung",
      "evidenceFamily": "hirschsprung_obstruction_confirmation_and_staged_care",
